    ['Qwen2.5-32B','79.8 → 79.2 (-0.6)','91.5 → 90.8 (-0.7)','65.1 → 64.0 (-1.1)','46.8 → 45.9 (-0.9)'],
    ['Mixtral-8x7B','77.4 → 76.8 (-0.6)','89.9 → 89.2 (-0.7)','61.3 → 60.0 (-1.3)','43.5 → 42.8 (-0.7)']
  ];
  s.addTable(rows, {
    x:0.7, y:1.55, w:12.0, h:3.8,
    fontSize:11,
    color:C.text,
    border:{pt:1,color:C.line},
    fill:'FFFFFF',
    valign:'mid',
    colW:[2.25,2.35,2.35,2.35,2.35],
    rowH:[0.5,0.54,0.54,0.54,0.54,0.54,0.54]
