}

// 8 TEE solution
{
  const s = pptx.addSlide();
  s.background = { color: C.bgLight };
  addHeader(s, 'Trusted Execution Environments Provide Provable Cryptographic Model Integrity');

  s.addShape(pptx.ShapeType.roundRect,{x:0.7,y:1.2,w:5.9,h:5.7,fill:{color:'FFFFFF'},line:{color:C.line,pt:1}});
  s.addText('TEE security model', {x:0.95,y:1.45,w:2.8,h:0.3,fontSize:15,bold:true,color:C.title});
