  s.addShape(pptx.ShapeType.roundRect,{x:6.95,y:1.2,w:5.65,h:5.7,fill:{color:'FFFFFF'},line:{color:C.line,pt:1}});
  s.addText('Software tests vs TEEs', {x:7.2,y:1.45,w:3.7,h:0.3,fontSize:15,bold:true,color:C.title});
