    ['Robust to adversarial routing','No','Yes'],
    ['Hardware/software nondeterminism impact','High','Low (attestation binds environment)'],
    ['Operational cost','High query cost','Modest runtime overhead'],
    ['Deployment path','Ad hoc auditing','Confidential computing (e.g., NVIDIA)']
  ];
  s.addTable([['Property','Software-only','TEE-based'], ...comp], {
    x:7.2, y:1.88, w:5.15, h:3.9, fontSize:10.5, color:C.text,
    border:{pt:1,color:C.line}, fill:'FFFFFF', colW:[1.8,1.5,1.85], rowH:[0.48,0.64,0.64,0.8,0.64,0.8]
  });
}

// 9 takeaways
{
  const s = pptx.addSlide();
  s.background = { color: C.bgDark };
  s.addText('Key Takeaways: Close the Verification Gap with Hardware Attestation', { x:0.7, y:0.7, w:12.0, h:0.7, fontSize:30, bold:true, color:C.white });

  const points = [
    'Model substitution is economically rational and difficult to detect from outputs alone.',
    'FP8 quantization often preserves benchmark performance closely, reducing observable signal.',
    'Log-probability fingerprints break under real-world inference nondeterminism.',
    'Randomized substitution can make statistical detection query-prohibitive.',
    'TEEs provide the actionable path: attest what model actually executed, not what behavior suggests.'
  ];
  points.forEach((p,i)=>{
    const y = 1.75 + i*0.95;
    s.addShape(pptx.ShapeType.roundRect,{x:0.85,y:y,w:11.6,h:0.72,fill:{color:i===4?'1A2B5F':'121C3A'},line:{color:'2A3F79',pt:1}});
    s.addShape(pptx.ShapeType.ellipse,{x:1.05,y:y+0.16,w:0.33,h:0.33,fill:{color:i===4?'00A3A3':'2E6BFF'},line:{color:i===4?'00A3A3':'2E6BFF'}});
    s.addText(p,{x:1.5,y:y+0.16,w:10.6,h:0.4,fontSize:14,color:'E5EBFF'});
  });

  s.addShape(pptx.ShapeType.roundRect,{x:0.85,y:6.65,w:11.6,h:0.55,fill:{color:'00A3A3'},line:{color:'00A3A3'}});
  s.addText('Call to action: Standardize attestation-backed API verification before high-stakes LLM deployment.', {x:1.0,y:6.8,w:11.2,h:0.3,fontSize:13,bold:true,color:C.white,align:'center'});
}

pptx.writeFile({ fileName: '/app/output/final_deck.pptx' });
